import configGenerator from '@leyman/eslint-config';
import packageJson from './package.json' with { type: 'json' };

export default [
    ...(await configGenerator({ configUrl: import.meta.url, packageJson })),
    {
        // The parser runs anywhere, so Node.js globals are left out, but the CLI only runs on Node.js.
        files: ['src/cli.ts'],
        languageOptions: { globals: { process: 'readonly' } },
    },
    {
        // Generated by the tests from fixture XSDs: held to the type check and to matching the generator, not to
        // this repository's style, which XML names and printed types can't follow (`#any` keys, a type and a
        // const of one name).
        ignores: ['test/generated/**'],
    },
];
